106	
107	  // A repo that declares the RETIRED mechanism is not served by anything: Phase 5
108	  // deleted it. Standing down silently would leave that repo unmaintained with a
109	  // green run to show for it, so the dead end is named and the fix stated.
110	  const served = servedBy(declaration);
111	  if (served.mechanism !== 'updates') {
112	    console.error(`update: this repo declares maintenance.mechanism "${served.mechanism}", which was retired in`
113	      + ' Claudinite #768 Phase 5 — nothing maintains this repo. Set it to "updates" (or remove the key: that is'
114	      + ' now the default) to be served by the update flows.');
115	    process.exit(1);
116	  }
117	  const { delivery } = resolveDelivery(declaration?.maintenance?.delivery);
118	  if (!delivery) {
119	    console.error(`update: maintenance.delivery "${declaration?.maintenance?.delivery}" is neither auto-merge nor review`);
120	    process.exit(1);
121	  }
122	
123	  // DISPOSE OF THE INCUMBENT FIRST (#787). A cycle that could not land its PR — the
124	  // usual cause is a `pull_request` run parked at `action_required` while the
125	  // dispatched one goes green seconds after the wait gave up — leaves it open for
126	  // "the next run to dispose of". This is that disposal, and it must happen BEFORE
127	  // the converge for the reason the bug existed: a cycle that finds nothing to do
128	  // returns early, so disposal placed after the converge is unreachable on exactly
129	  // the quiet cycle that should perform it. A cycle that cannot clear the way does
130	  // not deliver on top of it — one update PR is alive at a time, or none.
131	  const open = rehearsalRef ? { json: [] } : await gh(token, `/repos/${repo}/pulls?state=open&per_page=100`);
132	  const incumbent = openDeliveredPull(open.json, UPDATE_PREFIX);
133	  if (incumbent) {
134	    const disposal = await disposeOpenPull({
135	      token, repo, pr: incumbent, delivery, log: (s) => console.log(`update: ${s}`),
136	    }).catch((e) => { console.log(`update: disposing of PR #${incumbent.number} failed: ${e.message}`); return 'kept'; });
137	    if (disposal === 'kept') {
138	      console.log(`update: PR #${incumbent.number} still stands — this cycle cannot deliver on top of it`);
139	      return;
140	    }
141	    if (disposal === 'merged') {
142	      console.log(`update: landed PR #${incumbent.number}; main has moved past this checkout — next cycle converges from it`);
143	      return;
144	    }
145	  }
146	
