148	  // the thing being replaced, and a flow executing its own stale copy is how a broken
149	  // update makes itself permanent.
150	  const tmp = mkdtempSync(join(tmpdir(), 'claudinite-canon-'));
151	  try {
152	    // A rehearsal names the ref it is qualifying; an ordinary cycle takes the
153	    // default branch, which is the only thing a member should ever converge onto.
154	    git(rehearsalRef
155	      ? ['clone', '--depth', '1', '--branch', rehearsalRef, CANON_URL, tmp]
156	      : ['clone', '--depth', '1', CANON_URL, tmp]);
157	    const load = async (rel) => import(pathToFileURL(join(tmp, rel)).href);
158	    const { engineUpdate } = await load('updates/engine-update.mjs');
159	    const { packUpdate } = await load('updates/pack-update.mjs');
160	    const { terminalFor } = await load('updates/terminals.mjs');
161	
162	    // ENGINE FIRST, always: a pack declares the minimum engine it runs on, and the
163	    // pack flow enforces that against what this repo HAS. Running packs first would
164	    // check every pack against yesterday's engine and block updates that the very
165	    // next step would have made legal.
166	    const engine = await engineUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
167	    console.log(`update: engine — ${engine.status}: ${engine.detail}`);
168	    let packs = null;
169	    if (engine.status !== 'needs-human') {
170	      packs = await packUpdate(root, { fullName: repo, delivery, selfTestRun: undefined });
171	      console.log(`update: packs — ${packs.status}: ${packs.detail}`);
172	    }
173	
174	    // The engine's terminal wins when it stopped the run: nothing downstream of a
175	    // refused engine update is trustworthy, including a pack flow that never ran.
176	    const outcome = engine.status === 'needs-human' ? engine : packs;
177	    const terminal = terminalFor(outcome);
178	
179	    // A REHEARSAL STOPS HERE. It has the only answer it was asked for — does this
180	    // canon ref converge this member and leave it green — so it says so and puts the
181	    // tree back exactly as it found it. Restoring is not tidiness: an uncommitted
182	    // converge left behind would be picked up by the canary's own next cycle as if a
183	    // human had written it.
184	    if (rehearsalRef) {
185	      git(['-C', root, 'checkout', '--', '.']);
186	      git(['-C', root, 'clean', '-fd']);
187	      if (terminal.action === 'needs-human') {
188	        console.error(`update: rehearsing ${rehearsalRef} FAILED — ${terminal.why}`);
189	        process.exit(1);
190	      }
191	      console.log(`${REHEARSAL_MARKER} ${repo} against ${rehearsalRef} — ${terminal.action}: ${terminal.why}`);
192	      return;
193	    }
194	
195	    const changed = git(['-C', root, 'status', '--porcelain']).trim();
196	    if (!changed && terminal.action !== 'needs-human') {
197	      console.log('update: nothing changed — no branch, no PR');
198	      return;
199	    }
200	
201	    const day = new Date().toISOString().slice(0, 10);
202	    const seed = Math.random().toString(36).slice(2, 8);
203	    const branch = updateBranchName(day, seed);
204	    git(['-C', root, 'checkout', '-B', branch]);
205	    git(['-C', root, 'add', '-A']);
206	    const staged = git(['-C', root, 'diff', '--cached', '--name-only']).split('\n').filter(Boolean);
207	    const { title, body } = updatePullText(terminal, { engine, packs });
208	    git(['-C', root, '-c', 'user.name=claudinite[bot]', '-c', 'user.email=claudinite@users.noreply.github.com',
209	      'commit', ...(staged.length ? [] : ['--allow-empty']), '-m', title]);
210	    git(['-C', root, 'push', '--force', `https://x-access-token:${token}@github.com/${repo}.git`, `HEAD:refs/heads/${branch}`]);
211	
212	    const created = await gh(token, `/repos/${repo}/pulls`, { method: 'POST', body: { head: branch, base, title, body } });
213	    const failure = pullCreateError(created.status, created.json);
214	    if (failure) throw new Error(`could not open the update PR for ${branch}: ${failure}`);
215	    const pr = created.json;
216	    console.log(`update: opened PR #${pr.number} on ${branch} (${terminal.action})`);
217	
218	    // The terminal, acted on. Only one action merges, and it is the one the flow
219	    // already judged green — everything else leaves the PR standing, labelled or
220	    // handed to the agent stage.
221	    if (terminal.action === 'merge') {
222	      await landDelivery({ token, repo, base, pr, delivery });
223	    } else if (terminal.action === 'needs-human') {
224	      await gh(token, `/repos/${repo}/issues/${pr.number}/labels`, { method: 'POST', body: { labels: [terminal.label] } });
225	      console.log(`update: left PR #${pr.number} open and labelled ${terminal.label} — ${terminal.why}`);
226	    } else if (terminal.action === 'apply-stage' && requestFile) {
227	      writeFileSync(requestFile, `${JSON.stringify({
228	        marker: 'agent-requested',
229	        delivered: { branch, pr: pr.number, merged: false },
230	        reason: { code: 'apply-stage', detail: terminal.why },
231	      })}\n`);
232	      console.log(`update: requested the apply stage — ${terminal.why}`);
233	    }
234	  } finally {
235	    rmSync(tmp, { recursive: true, force: true });
236	  }
237	}
238	
239	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
240	  main().catch((e) => { console.error(`update failed: ${e.message}`); process.exit(1); });
241	}
