    ...(engine?.from !== engine?.to ? [`engine ${engine?.from ?? 'unstamped'} → ${engine?.to}`] : []),
    ...(packs?.plan ?? []).filter((p) => p.from !== p.to).map((p) => `${p.id} ${p.from ?? 'unstamped'} → ${p.to}`),
  ];
